import type { PointKey, ZodiacSign } from "../types";

/**
 * Textes dédiés pour les placements les plus lus (Soleil, Lune, Mercure,
 * Vénus, Mars, Jupiter, Saturne, Ascendant) × 12 signes — Jupiter et Saturne
 * changent de signe tous les ~1 à 2,5 ans, assez lentement pour marquer une
 * classe d'âge mais assez vite pour rester une donnée réellement
 * personnelle, contrairement à Uranus/Neptune/Pluton (plusieurs décennies
 * par signe) qui restent générationnelles : pour ces trois-là et le Nœud
 * Nord, voir `compose.ts`, qui compose un texte à partir de l'essence de la
 * planète et de la tonalité du signe plutôt que d'inventer une nuance
 * individuelle qui n'existerait pas vraiment à cette échelle de temps.
 */
export const PLANET_IN_SIGN: Partial<Record<PointKey, Record<ZodiacSign, string>>> = {
  sun: {
    belier: "Le Soleil en Bélier fonctionne par l'élan : l'identité se prouve dans l'action, dans la capacité à initier, foncer, être le premier — l'énergie vitale a besoin de terrain de conquête pour exister pleinement. La tension se loge dans l'après-coup : une fois l'obstacle franchi ou la nouveauté retombée, l'intérêt peut s'effondrer aussi vite qu'il est monté, et l'ego a du mal à trouver sa place quand il n'y a plus rien à conquérir. Le terrain de maturation est là : apprendre que la valeur de soi ne se mesure pas qu'à la vitesse de la première réaction, et que tenir un projet jusqu'au bout construit une confiance plus durable que l'élan seul.",
    taureau: "Le Soleil en Taureau construit son identité par l'accumulation lente : on existe en tenant, en stabilisant, en donnant de la valeur à ce qui dure — chaque acquis concret (un lieu, un savoir-faire, une relation) devient un pilier de qui l'on est. Le point sensible se niche dans le changement : ce qui rassure peut aussi enfermer, et la peur de perdre ce qui a été construit freine parfois des évolutions pourtant nécessaires. La leçon à intégrer est d'apprendre qu'on peut lâcher une forme sans perdre la valeur qu'elle contenait — que la sécurité intérieure ne dépend pas uniquement de ce qui reste identique.",
    gemeaux: "Le Soleil en Gémeaux se définit par le mouvement de l'esprit : l'identité se construit en reliant, en commentant, en passant d'un sujet à l'autre — exister, c'est être en dialogue avec le monde plutôt que figé dans une seule vérité. La friction se joue surtout dans la cohérence : le besoin permanent de nouveauté peut donner l'image de quelqu'un qui change d'avis ou de façade selon l'interlocuteur, et l'engagement profond dans un seul sujet ou une seule personne peut sembler menacer la liberté de circuler. Le terrain de maturation est de découvrir qu'approfondir n'est pas s'enfermer — qu'on peut rester curieux tout en ayant un centre stable auquel revenir.",
    cancer: "Le Soleil en Cancer construit l'identité à partir du lien : on existe en protégeant, en se souvenant, en appartenant à une histoire familiale ou affective qui précède et dépasse l'individu. L'ombre de ce placement se cache dans l'exposition : s'affirmer publiquement ou prendre sa place au grand jour peut se heurter à la peur d'être blessé ou rejeté, si bien que la carapace protectrice finit parfois par étouffer l'expression de soi qu'elle était censée protéger. Le travail intérieur consiste à apprendre que la sécurité peut aussi se construire en s'exposant, pas seulement en se retranchant — que le monde extérieur n'est pas systématiquement une menace pour ce qui est précieux à l'intérieur.",
    lion: "Le Soleil est chez lui en Lion : l'identité se construit par le rayonnement, la création, le besoin d'exister aux yeux des autres avec panache — être vu n'est pas une vanité superficielle mais une condition presque vitale de l'estime de soi. Ce qui coûte le plus se joue dans la dépendance au regard : quand la reconnaissance manque, la confiance peut s'effondrer bien plus vite que ne le laisse deviner l'assurance affichée, et la fierté rend difficile de demander de l'aide ou d'admettre une faille. Ce qu'il y a à travailler ici est d'apprendre à puiser la valeur de soi à l'intérieur autant qu'à l'extérieur, pour que le rayonnement devienne un don plutôt qu'une quête permanente d'approbation.",
    vierge: "Le Soleil en Vierge se construit par l'utile : l'identité se prouve dans le travail bien fait, la précision, la capacité à améliorer ce qui existe — l'estime de soi passe presque toujours par un service rendu ou une compétence exercée. Le nœud se trouve dans l'auto-jugement : l'exigence tournée vers l'extérieur se retourne facilement contre soi-même, et le sentiment de ne jamais en faire assez peut ronger la confiance même quand les résultats sont là. Grandir ici consiste à apprendre que la valeur de soi ne se mesure pas seulement à ce qui a été corrigé ou perfectionné — qu'on a le droit d'exister sans être irréprochable.",
    balance: "Le Soleil en Balance se construit dans le miroir de l'autre : l'identité se précise et se confirme à travers la relation, l'échange, le regard du vis-à-vis — exister seul, sans confrontation à un autre point de vue, peut sembler incomplet. La difficulté principale se loge dans l'affirmation personnelle : le souci constant de l'équilibre et de ne pas déplaire peut conduire à taire ses propres désirs, jusqu'à perdre de vue ce qu'on veut vraiment derrière ce qu'on pense que l'autre attend. Le terrain de maturation est d'apprendre à trancher et à déplaire sans perdre l'amour de l'autre — que l'harmonie durable passe parfois par un désaccord assumé.",
    scorpion: "Le Soleil en Scorpion construit l'identité dans l'intensité et le contrôle : on existe en allant au fond des choses, en refusant la superficialité, avec un besoin presque vital de comprendre ce qui se joue sous la surface — de soi-même comme des autres. Le revers se joue dans la confiance : la peur d'être trahi ou dominé pousse à garder la maîtrise, à tester l'autre avant de se livrer, ce qui peut isoler autant que protéger. Ce placement invite à apprendre que le pouvoir véritable ne réside pas que dans le contrôle, mais aussi dans la capacité à se rendre vulnérable sans que cela signifie perdre — que la transformation, une fois traversée, libère plus qu'elle ne menace.",
    sagittaire: "Le Soleil en Sagittaire se construit par la quête de sens : l'identité se déploie en explorant, en croyant en quelque chose de plus grand que le quotidien, avec un besoin réel d'horizon et de mouvement pour rester soi-même. La tension se loge dans l'ancrage : l'enthousiasme pour ce qui vient facilite l'engagement initial mais rend parfois difficile de tenir la durée, une fois la nouveauté et la promesse d'aventure retombées. La vraie maturation consiste à apprendre que la liberté ne s'oppose pas forcément à l'engagement — qu'on peut explorer en profondeur un seul territoire plutôt que de multiplier les horizons pour fuir la routine.",
    capricorne: "Le Soleil en Capricorne construit l'identité dans la durée : on existe en portant ses responsabilités, en gravissant patiemment, avec un besoin de mériter sa place plutôt que de la recevoir gratuitement. Le point sensible se niche dans la légèreté : le sérieux précoce, souvent hérité d'un besoin de se montrer fiable très tôt, peut rendre difficile de se reposer, de jouer, de recevoir sans avoir à le mériter par l'effort. Le terrain de maturation consiste à apprendre que l'autorité et la réussite n'ont pas besoin d'être arrachées à chaque instant — qu'on peut relâcher le contrôle sans perdre ce qui a été construit.",
    verseau: "Le Soleil en Verseau construit l'identité par la différence assumée : on existe en pensant autrement, en refusant de se fondre dans le moule, avec un besoin réel d'appartenir à quelque chose de plus large que soi tout en restant irréductiblement singulier. La friction se joue surtout dans l'intimité : la distance qui protège l'indépendance peut aussi tenir les autres à l'écart plus qu'on ne le voudrait, et l'émotion brute est parfois plus difficile à assumer que l'idée. La leçon à intégrer est d'apprendre que se rapprocher n'annule pas la singularité — qu'on peut appartenir à un lien sans s'y dissoudre.",
    poissons: "Le Soleil en Poissons construit une identité fluide, perméable, qui existe en se reliant à quelque chose de plus vaste — une inspiration, une cause, une émotion collective — plutôt qu'en s'affirmant comme un contour bien délimité. L'ombre de ce placement se cache dans les frontières : l'empathie et la porosité facilitent le lien mais rendent parfois difficile de savoir où s'arrête soi-même et où commence l'autre, au risque de se dissoudre dans les besoins ou les émotions d'autrui. La vraie maturation consiste à apprendre à poser des limites sans se refermer — que la sensibilité peut rester un don même une fois canalisée par une forme plus claire.",
  },
  moon: {
    belier: "La Lune en Bélier réagit avant de réfléchir : le besoin de sécurité se traduit en énergie immédiate, en action ou en parole plutôt qu'en retrait — l'émotion se décharge vite, ce qui évite de la laisser s'accumuler mais laisse aussi peu de place à l'introspection. Ce qui coûte le plus se joue dans la vulnérabilité : la vitesse de la réaction protège de ressentir pleinement ce qui est difficile, et la colère ou l'impatience masquent souvent une blessure ou une peur plus profonde qui n'a pas eu le temps d'être identifiée. Le travail intérieur consiste à apprendre à ralentir juste assez pour sentir ce qui se cache derrière la réaction immédiate, sans pour autant perdre la spontanéité qui est aussi une vraie force.",
    taureau: "La Lune en Taureau se rassure par le sensoriel et le stable : le besoin de sécurité affective passe par le corps, la routine, la présence rassurante de ce qui ne change pas — le réconfort est presque physique avant d'être verbal. Le nœud se trouve dans le changement : ce qui apaise peut aussi devenir une résistance, un attachement si fort aux habitudes et aux personnes connues que toute perturbation, même positive, est vécue comme une menace. La vraie maturation consiste à apprendre que la sécurité intérieure peut survivre au changement de décor — que la stabilité se construit aussi en soi, pas seulement dans ce qui entoure.",
    gemeaux: "La Lune en Gémeaux traite l'émotion par la parole et la pensée : nommer, raconter, analyser ce qui est ressenti est souvent le seul moyen d'apprivoiser une émotion, comme si la mettre en mots la rendait plus supportable. La difficulté principale se loge dans le ressenti brut : cette médiation mentale permanente peut créer une distance avec l'émotion elle-même, au point de bien la décrire sans jamais vraiment la traverser ou la digérer. Ce qu'il y a à travailler ici est d'apprendre à rester avec une émotion silencieuse, sans avoir besoin de la formuler immédiatement pour la légitimer.",
    cancer: "La Lune est chez elle en Cancer : la sensibilité est directe, sans filtre, avec une mémoire affective qui garde la trace de chaque lien important — le besoin de nid, d'appartenance et de protection est un moteur central, presque instinctif. Le revers se joue dans la dépendance au passé : cette mémoire si vive peut rejouer d'anciennes blessures dans le présent, colorant une situation neuve avec les peurs d'une histoire ancienne qui n'a plus vraiment cours. La leçon à intégrer est d'apprendre à distinguer ce qui appartient au passé de ce qui se joue réellement aujourd'hui, pour que la mémoire protège sans emprisonner.",
    lion: "La Lune en Lion a besoin d'aimer et d'être aimée avec éclat : la sécurité affective se construit dans la reconnaissance visible, dans le fait de compter clairement pour quelqu'un plutôt que dans un lien discret ou tacite. La tension se loge dans la fierté : demander de l'aide ou montrer une vulnérabilité brute peut sembler humiliant, si bien que la douleur se cache souvent derrière une façade de force ou de dignité qui empêche l'autre de vraiment s'approcher. Grandir ici consiste à apprendre que la vulnérabilité assumée, loin de diminuer, peut au contraire renforcer le lien et l'admiration qu'on cherche tant.",
    vierge: "La Lune en Vierge calme l'anxiété par l'action utile : ranger, organiser, rendre service, corriger un détail — s'occuper les mains et l'esprit devient un moyen de gérer une émotion qui, exprimée directement, semble trop désordonnée ou trop exposée. Le point sensible se niche dans l'auto-critique : cette même exigence appliquée à soi-même peut transformer une inquiétude ordinaire en sentiment chronique de ne jamais faire ou être assez bien. Le travail intérieur consiste à apprendre à recevoir du réconfort sans avoir à le mériter par un service rendu, et à accepter le désordre émotionnel sans chercher immédiatement à le corriger.",
    balance: "La Lune en Balance a besoin d'harmonie relationnelle pour se sentir en sécurité : le climat émotionnel de l'entourage compte presque autant que ce qui se passe à l'intérieur de soi, et la tension ou le conflit sont vécus comme une vraie menace intérieure. La friction se joue surtout dans l'authenticité : ce besoin d'apaiser et de plaire peut conduire à taire un vrai désaccord ou une émotion négative pour préserver la paix, au risque de l'accumuler en silence jusqu'à ce qu'elle ressorte de façon disproportionnée. Ce placement invite à apprendre que l'expression d'un désaccord honnête ne détruit pas nécessairement le lien — qu'elle peut au contraire l'approfondir.",
    scorpion: "La Lune en Scorpion ne vit rien à moitié : les émotions sont ressenties dans toute leur intensité, souvent en silence, avec une lucidité presque instinctive pour repérer ce qui est caché, non-dit ou manipulé chez les autres — un vrai radar émotionnel, mais aussi une vulnérabilité rarement montrée. L'attachement, une fois donné, se vit comme un engagement total : c'est une Lune profondément fidèle, capable d'une loyauté à toute épreuve envers qui a gagné sa confiance, et pour qui la trahison — réelle ou seulement perçue — laisse une marque durable, presque impossible à effacer complètement. L'ombre de ce placement se cache dans la confiance : la peur d'être trahi·e ou blessé·e pousse à garder le contrôle, à tester la loyauté de l'autre avant de baisser la garde, ce qui peut créer une solitude affective même dans une relation proche — le besoin de vérité affective est réel, mais il s'accompagne d'une difficulté à croire qu'on peut être aimé·e sans condition ni épreuve. Ce qu'il y a à travailler ici est d'apprendre que se livrer sans garantie n'est pas la même chose que perdre le contrôle — que la vraie force n'est pas de tout maîtriser, mais d'accepter d'être vu·e en entier, y compris dans ce qui est fragile, sans que cela ne devienne une arme entre les mains de l'autre. C'est aussi une Lune qui métabolise les crises mieux que n'importe quelle autre : ce qui la traverse la transforme profondément, rarement à la surface.",
    sagittaire: "La Lune en Sagittaire trouve sa sécurité dans le mouvement et l'espace : le besoin affectif se satisfait autant par la liberté de bouger, d'explorer, de croire en quelque chose de plus grand que par l'ancrage dans un lieu ou une routine fixe. Ce qui coûte le plus se joue dans l'engagement : la peur de se sentir enfermé·e peut pousser à fuir au premier signe de pesanteur relationnelle, confondant parfois besoin d'air et véritable besoin de rupture. Grandir ici consiste à apprendre qu'on peut rester engagé·e tout en gardant de l'espace — que la liberté intérieure ne dépend pas uniquement de la liberté de partir.",
    capricorne: "La Lune en Capricorne se protège par la maîtrise de soi : l'émotion est vécue en privé, rarement montrée, avec une pudeur qui vient souvent d'avoir appris tôt à se montrer solide plutôt que d'être materné·e ou rassuré·e. Le nœud se trouve dans la demande : il est difficile de demander de l'aide ou du réconfort, comme si le faire révélait une faiblesse inacceptable, si bien que le besoin affectif profond reste souvent invisible même aux proches. Ce placement invite à apprendre que recevoir du soutien n'annule pas la compétence ni la force — que la sécurité affective construite tardivement peut devenir, une fois acquise, l'une des plus solides qui soit.",
    verseau: "La Lune en Verseau vit l'émotion avec une distance mentale : comprendre et analyser ce qui est ressenti précède souvent le fait de le vivre pleinement, et le besoin de liberté reste réel même dans les liens les plus proches — l'amitié et l'indépendance comptent parfois autant que la fusion. La difficulté principale se loge dans la proximité : cette distance protectrice peut être perçue par l'autre comme un détachement ou un manque d'implication, alors qu'elle est surtout une façon de gérer une intensité émotionnelle qui déstabilise. La leçon à intégrer est d'apprendre à se laisser toucher sans perdre son indépendance — que l'intimité n'exige pas de renoncer à la liberté intérieure.",
    poissons: "La Lune en Poissons ressent tout, parfois sans filtre entre ce qui vient de soi et ce qui vient des autres : l'empathie est immédiate, presque instinctive, avec un besoin réel de retrait, de rêverie ou de spiritualité pour se retrouver après avoir absorbé les émotions ambiantes. Le revers se joue dans les limites : cette porosité peut conduire à se perdre dans les besoins d'autrui, à confondre compassion et sacrifice de soi, jusqu'à ne plus savoir ce qu'on ressent vraiment derrière ce qu'on ressent pour les autres. Le terrain de maturation consiste à apprendre à poser une limite sans se sentir coupable, et à distinguer l'émotion qui est vraiment la sienne de celle qu'on a absorbée.",
  },
  mercury: {
    belier: "Mercure en Bélier pense en mode réactif : l'esprit saisit une information et tranche presque immédiatement, avec une vivacité qui donne un vrai avantage dans le débat ou la prise de décision rapide. La tension se loge dans la nuance : trancher vite laisse peu de place à l'examen complet d'une question, et la conviction affichée peut devancer la réflexion réellement aboutie. La vraie maturation consiste à apprendre à ralentir juste assez pour vérifier une première impression avant de la défendre bec et ongles — sans perdre la rapidité qui reste un vrai atout.",
    taureau: "Mercure en Taureau pense avec lenteur assumée : une idée a besoin de temps pour s'installer, d'être éprouvée dans le concret, avant d'être vraiment adoptée — mais une fois formée, elle devient une conviction quasi inébranlable. Le point sensible se niche dans la flexibilité : cette solidité mentale peut se transformer en fermeture d'esprit, un refus d'examiner un nouvel argument simplement parce qu'il dérange une opinion déjà installée. Le travail intérieur consiste à apprendre qu'accepter de reconsidérer une idée n'est pas une faiblesse — que la solidité peut cohabiter avec la souplesse.",
    gemeaux: "Mercure est ici dans son élément : la pensée fonctionne par association rapide, saute d'un sujet à l'autre avec aisance, et le plaisir du contact verbal et de l'apprentissage rapide est presque un besoin vital. La friction se joue surtout dans la profondeur : cette agilité peut empêcher de rester assez longtemps sur un sujet pour vraiment le maîtriser, et la parole peut parfois précéder une pensée encore mal formée. La leçon à intégrer est d'apprendre à choisir consciemment où investir un effort de concentration prolongé, pour que la curiosité débouche parfois sur une vraie expertise plutôt que sur un savoir toujours superficiel.",
    cancer: "Mercure en Cancer pense à travers le filtre de la mémoire et de l'émotion : une information n'est jamais traitée froidement, elle est reliée à un vécu, une ambiance, un ressenti familial qui la colore. L'ombre de ce placement se cache dans l'objectivité : ce mode de pensée intuitif peut faire resurgir d'anciennes peurs dans un raisonnement présent, brouillant la frontière entre ce qui est réellement en jeu et ce qui rappelle une blessure passée. La vraie maturation consiste à apprendre à identifier quand une réaction mentale appartient au présent et quand elle rejoue un souvenir, sans pour autant renier la richesse de cette intelligence intuitive.",
    lion: "Mercure en Lion pense pour convaincre : l'expression a besoin de marquer les esprits, de raconter une histoire avec conviction, et l'idée elle-même devient souvent une extension de l'identité qu'on défend. Ce qui coûte le plus se joue dans l'écoute : cette conviction affirmée peut rendre difficile d'entendre réellement un avis contraire sans le vivre comme une remise en question personnelle. Le travail intérieur consiste à apprendre à séparer la solidité d'une idée de la fierté qui la porte — pour pouvoir changer d'avis sans avoir le sentiment de perdre la face.",
    vierge: "Mercure est également très à l'aise en Vierge : l'esprit analyse avec précision, repère le détail qui cloche, et préfère toujours ce qui est vérifiable à ce qui reste approximatif. Le nœud se trouve dans l'auto-critique : ce même sens critique tourné vers l'intérieur peut transformer une pensée normalement rigoureuse en rumination anxieuse, incapable de se satisfaire d'une conclusion \"assez bonne\". La leçon à intégrer est d'apprendre que l'exactitude n'est pas toujours nécessaire pour avancer — que le doute méthodique a une limite au-delà de laquelle il devient paralysant.",
    balance: "Mercure en Balance pense en pesant systématiquement le pour et le contre : chaque idée est examinée à travers son opposé, dans une recherche constante d'équilibre et de formulation diplomate. La difficulté principale se loge dans la décision : ce souci permanent de voir les deux côtés d'un argument peut rendre difficile de trancher clairement, au point de privilégier un discours consensuel plutôt qu'une position affirmée. Ce qu'il y a à travailler ici est d'apprendre qu'une opinion tranchée n'est pas nécessairement injuste — qu'on peut choisir un camp sans renoncer à la capacité de comprendre l'autre.",
    scorpion: "Mercure en Scorpion pense en creusant sous la surface : l'esprit ne se satisfait jamais d'une explication de façade, il cherche systématiquement le sous-entendu, le motif caché, ce qui n'est pas dit à voix haute. Le revers se joue dans la méfiance : cette lucidité psychologique peut virer au soupçon permanent, prêtant des intentions cachées même là où il n'y en a pas. Le travail intérieur consiste à apprendre à utiliser cette perspicacité comme un outil de compréhension plutôt que comme une arme défensive systématique — à faire confiance parfois, sans pour autant renoncer au discernement.",
    sagittaire: "Mercure en Sagittaire pense en grand : l'esprit préfère la vue d'ensemble, la grande idée ou la conviction philosophique aux détails qui semblent secondaires, avec une franchise directe qui va droit au but. La tension se loge dans la précision : cette préférence pour la vision large peut faire perdre des nuances importantes, et la franchise peut heurter sans que ce soit l'intention. Grandir ici consiste à apprendre que le détail n'est pas l'ennemi de la vision — qu'on peut garder une conviction large tout en prenant le temps de vérifier ce qui la fonde vraiment.",
    capricorne: "Mercure en Capricorne pense avec méthode : l'esprit va à l'essentiel, structure ses idées avant de les exprimer, et oriente presque toujours sa réflexion vers une application concrète et durable. Le point sensible se niche dans la spontanéité : cette rigueur peut brider l'expression d'une idée encore floue ou d'un ressenti pas encore rationalisé, comme si seule une pensée déjà aboutie méritait d'être partagée. Ce qu'il y a à travailler ici est d'apprendre à penser à voix haute, sans avoir besoin que chaque idée soit déjà solide et prouvée avant de l'exprimer.",
    verseau: "Mercure en Verseau pense en dehors du cadre établi : l'esprit aime envisager l'avenir autrement, remettre en question ce qui semble acquis, avec une réelle capacité d'abstraction et de vision systémique. La friction se joue surtout dans l'ancrage émotionnel : cette pensée qui prend de la distance peut devenir un moyen d'éviter le ressenti, en traitant une question personnelle comme un simple problème théorique à résoudre. Ce placement invite à apprendre à laisser une idée rester reliée à ce qu'elle signifie humainement, sans la réduire à un concept froid et détaché.",
    poissons: "Mercure en Poissons pense par association et par image plutôt que par logique linéaire : l'intuition précède souvent l'argument rationnel, et une idée peut naître d'un ressenti avant même d'être formulée en mots. L'ombre de ce placement se cache dans la précision factuelle : cette pensée fluide, précieuse pour la créativité, se prête mal à l'exactitude rigoureuse, et les détails concrets peuvent se brouiller ou se perdre en chemin. Grandir ici consiste à apprendre à donner une forme claire à une intuition juste, sans la trahir en la forçant dans une logique qui ne lui correspond pas.",
  },
  venus: {
    belier: "Vénus en Bélier désire par élan spontané : l'attirance se déclenche vite, presque instinctivement, et la conquête elle-même — le jeu de la séduction, le désir d'obtenir — est souvent aussi excitante que la relation qui s'ensuit. Ce qui coûte le plus se joue dans la durée : cette énergie qui s'enflamme facilement peut retomber tout aussi vite une fois l'objectif atteint, laissant l'engagement long terme moins naturel que l'élan initial. Ce placement invite à apprendre à retrouver, une fois la conquête faite, une nouvelle forme de désir — celle de continuer à choisir l'autre, jour après jour, plutôt que de chercher la prochaine étincelle ailleurs.",
    taureau: "Vénus est ici dans son élément : le désir s'exprime par le sensoriel, le confort partagé, une fidélité et un attachement qui se construisent lentement mais qui, une fois ancrés, sont d'une solidité rare. Le nœud se trouve dans le changement : cet attachement peut se transformer en possessivité ou en résistance à toute évolution du lien, par peur de perdre ce qui a mis si longtemps à s'installer. Le terrain de maturation consiste à apprendre que la sécurité affective peut survivre à un changement dans la relation — qu'aimer profondément n'exige pas de tout figer.",
    gemeaux: "Vénus en Gémeaux désire à travers l'échange : la séduction passe par les mots, l'esprit, la capacité à surprendre et à ne jamais ennuyer — le lien se nourrit de conversation autant que de contact physique. La difficulté principale se loge dans la constance : ce besoin permanent de variété et de stimulation peut rendre la routine relationnelle difficile à supporter, même quand elle n'est pas synonyme d'ennui réel. Ce qu'il y a à travailler ici est d'apprendre à retrouver de la nouveauté à l'intérieur même d'une relation stable, plutôt que de la chercher systématiquement ailleurs.",
    cancer: "Vénus en Cancer désire fusionner : l'affectivité cherche la sécurité dans le lien, le sentiment de faire famille avec l'autre, une tendresse protectrice qui s'exprime par le soin autant que par le désir. Le revers se joue dans la peur de la perte : cet attachement profond peut virer à la possessivité ou à une dépendance affective, où l'idée de l'abandon devient plus effrayante que le lien lui-même n'est nourrissant. Grandir ici consiste à apprendre que la sécurité affective peut aussi venir de soi-même — qu'aimer sans s'accrocher rend le lien plus libre, pas plus fragile.",
    lion: "Vénus en Lion désire avec panache : la séduction est généreuse, théâtrale même, et le plaisir d'aimer se double toujours d'un besoin d'être admiré·e en retour — on aime grand, on veut être aimé·e à la hauteur. La tension se loge dans l'orgueil : ce besoin de reconnaissance peut rendre difficile d'accepter un désaccord amoureux ou un refus sans le vivre comme une blessure d'ego. La vraie maturation consiste à apprendre que l'amour n'a pas besoin d'être constamment validé par l'admiration de l'autre pour être réel.",
    vierge: "Vénus en Vierge exprime le désir par le service : l'affectivité est pudique, elle passe par les gestes concrets, l'attention aux détails, le souci de bien faire pour l'autre plutôt que par de grandes déclarations. Le point sensible se niche dans l'auto-dévalorisation : ce souci de perfection appliqué à la relation peut faire naître un sentiment de ne jamais en faire assez, ou une difficulté à recevoir sans se sentir redevable. La vraie maturation consiste à apprendre à recevoir de l'amour sans avoir à le mériter par un service rendu, et à accepter qu'une relation imparfaite reste une relation valable.",
    balance: "Vénus est également très à l'aise en Balance : le désir cherche l'harmonie, l'équilibre à deux, un partenariat où le charme et l'esthétique relationnelle comptent presque autant que le sentiment lui-même. La friction se joue surtout dans l'affirmation de soi au sein du couple : ce besoin d'équilibre peut conduire à effacer ses propres désirs pour préserver la paix, jusqu'à perdre de vue ce qu'on veut vraiment derrière ce qu'on pense que l'autre attend. La leçon à intégrer est d'apprendre qu'un vrai désaccord exprimé ne détruit pas l'harmonie — qu'il peut au contraire la rendre plus authentique.",
    scorpion: "Vénus en Scorpion désire avec exclusivité : l'attachement ne se satisfait jamais de la superficialité, il cherche la fusion totale, la vérité affective, un engagement qui ne laisse aucune place au tiède ou à l'accessoire. L'ombre de ce placement se cache dans le contrôle : cette intensité peut virer à la jalousie ou à la possessivité, en particulier quand la confiance dans l'autre n'est pas encore totalement acquise. La leçon à intégrer est d'apprendre que l'intensité du sentiment n'a pas besoin d'un contrôle total sur l'autre pour rester réelle — que la confiance donnée librement rend le lien plus fort, pas plus vulnérable.",
    sagittaire: "Vénus en Sagittaire désire l'espace : l'affectivité a besoin de partager des idées, des aventures, un horizon commun, avec une vraie réticence à tout ce qui ressemble à un enfermement routinier. Ce qui coûte le plus se joue dans l'engagement : ce besoin de liberté peut être confondu, par soi-même ou par l'autre, avec une difficulté à s'investir vraiment dans la durée. Le travail intérieur consiste à apprendre qu'on peut s'engager pleinement tout en gardant de l'espace — que la liberté et la fidélité à un lien ne s'excluent pas forcément.",
    capricorne: "Vénus en Capricorne désire sérieusement : l'engagement se construit progressivement, sur des preuves concrètes plutôt que sur l'émotion du moment, et la séduction elle-même passe souvent au second plan derrière la construction patiente du lien. Le nœud se trouve dans la spontanéité : cette prudence affective peut retarder l'expression du désir ou de la vulnérabilité, par peur de s'exposer avant d'être certain·e que le lien tiendra. Le travail intérieur consiste à apprendre qu'un désir exprimé tôt n'est pas nécessairement un désir fragile — que la légèreté a aussi sa place dans un attachement destiné à durer.",
    verseau: "Vénus en Verseau désire librement : l'affectivité privilégie l'amitié, l'indépendance et l'originalité dans le lien, avec une vraie difficulté à accepter la routine ou la possessivité comme preuve d'amour. La difficulté principale se loge dans la proximité émotionnelle : cette distance protectrice peut être vécue par l'autre comme un manque d'investissement, même quand l'attachement est réel mais exprimé différemment. Ce qu'il y a à travailler ici est d'apprendre que se rapprocher émotionnellement n'efface pas l'indépendance — qu'on peut être proche sans être fusionnel.",
    poissons: "Vénus en Poissons désire fusionner dans l'idéal : l'affectivité est romantique, empathique, capable de se dévouer entièrement à l'autre et de sublimer une relation en quelque chose de presque sacré. Le revers se joue dans la lucidité : cette capacité à idéaliser peut masquer qui l'autre est réellement, et le sacrifice de soi devient parfois plus valorisé que le respect de ses propres limites. Ce qu'il y a à travailler ici est d'apprendre à aimer sans s'effacer — à garder un regard lucide sur l'autre sans perdre la capacité d'émerveillement qui rend cet amour si généreux.",
  },
  mars: {
    belier: "Mars est ici dans son élément : l'énergie s'exprime en ligne directe, sans détour, avec un besoin réel de relever des défis et d'agir avant même d'avoir fini de réfléchir. La tension se loge dans la durée : cette vitalité explosive s'épuise parfois aussi vite qu'elle s'est enflammée, et l'impatience peut saboter un objectif qui demandait de la persévérance plutôt qu'un premier élan. Grandir ici consiste à apprendre à canaliser cette énergie sur la durée d'un projet entier, pas seulement sur son démarrage — sans pour autant éteindre ce qui en fait la force.",
    taureau: "Mars en Taureau s'engage lentement mais avec une endurance redoutable : l'action démarre après un temps de latence, mais une fois lancée, elle ne s'arrête plus facilement, portée par une détermination presque inébranlable. Le point sensible se niche dans la colère : elle met longtemps à monter, ce qui peut laisser croire à une grande patience, mais quand elle éclate enfin, elle est difficile à calmer et met tout aussi longtemps à redescendre. Grandir ici consiste à apprendre à exprimer une frustration plus tôt, par petites touches, plutôt que de la laisser s'accumuler jusqu'à un point de rupture.",
    gemeaux: "Mars en Gémeaux agit par la parole et l'agilité mentale plutôt que par la force physique : le débat, l'argumentation rapide, le mot juste au bon moment sont ses véritables armes de combat. La friction se joue surtout dans la concentration : ce besoin de varier les fronts d'action peut disperser une énergie qui gagnerait à se concentrer sur un seul objectif à la fois, au risque de multiplier les débuts sans les finir. Ce placement invite à apprendre à choisir une bataille et à la mener jusqu'au bout, même quand une nouvelle idée plus excitante se présente en cours de route.",
    cancer: "Mars en Cancer combat de façon indirecte, plus défensive qu'offensive : l'énergie s'active surtout pour protéger les siens ou un territoire affectif menacé, rarement pour attaquer en terrain neutre. L'ombre de ce placement se cache dans l'expression directe de la colère : celle-ci a du mal à sortir frontalement et passe souvent par la bouderie, le repli ou l'allusion plutôt que par une confrontation ouverte. Ce placement invite à apprendre à dire un désaccord clairement, au moment où il se produit, plutôt que de le laisser infuser en silence jusqu'à ce qu'il ressorte de façon détournée.",
    lion: "Mars en Lion s'affirme avec panache : l'énergie a besoin d'être vue en train de réussir, l'action se double toujours d'une mise en scène de soi, et le courage réel se mêle à un ego qui cherche sa part de gloire. Ce qui coûte le plus se joue dans l'échec public : cette énergie fière a du mal à se tromper devant témoins, et la peur de perdre la face peut freiner une prise de risque pourtant nécessaire. Le terrain de maturation consiste à apprendre que l'échec assumé publiquement ne diminue pas la valeur de la personne — qu'on peut se tromper sans perdre son rayonnement.",
    vierge: "Mars en Vierge agit par méthode plutôt que par force brute : l'énergie s'applique au détail, à l'efficacité concrète, avec un vrai souci de bien faire plutôt que de faire vite. Le nœud se trouve dans l'auto-critique : ce même souci de perfection retourné vers soi peut freiner l'élan avant même qu'il ne commence, par peur de ne pas être à la hauteur. Ce placement invite à apprendre à agir avec une méthode \"assez bonne\" plutôt que parfaite, pour ne pas laisser l'exigence empêcher l'action elle-même.",
    balance: "Mars en Balance combat par la stratégie et la diplomatie plutôt que par l'affrontement direct : l'énergie cherche toujours le moyen le plus élégant, le plus juste, d'obtenir ce qu'elle veut sans détruire la relation. La difficulté principale se loge dans le passage à l'acte : cette préférence pour la mesure peut se transformer en indécision, en une tendance à temporiser bien au-delà du moment où il faudrait trancher et agir. Le terrain de maturation consiste à apprendre qu'un désaccord assumé clairement, même s'il déplaît un temps, reste souvent plus sain qu'un conflit évité qui couve indéfiniment.",
    scorpion: "Mars est traditionnellement très à l'aise en Scorpion : la détermination y est intense, presque inébranlable, avec une capacité de résistance et de contre-attaque rare, et une énergie pulsionnelle — sexuelle autant que combative — profondément marquée. Le revers se joue dans le contrôle : cette intensité peut se retourner en stratégie de pouvoir ou en volonté de tout maîtriser, y compris dans les situations où lâcher prise serait plus efficace. La vraie maturation consiste à apprendre que la puissance réelle n'a pas toujours besoin de se prouver par la victoire ou le contrôle total de la situation.",
    sagittaire: "Mars en Sagittaire s'engage avec enthousiasme pour des causes ou des idéaux : l'énergie a besoin de sens et de grand espace pour se déployer, avec une franchise directe qui peut être perçue comme abrupte. La tension se loge dans la constance : cet enthousiasme du départ peut retomber une fois la nouveauté passée, laissant un projet à moitié engagé au profit d'un nouvel horizon plus excitant. La vraie maturation consiste à apprendre à tenir un engagement même quand l'élan initial s'est estompé — que la vraie liberté inclut celle de rester.",
    capricorne: "Mars en Capricorne s'inscrit dans la durée : l'énergie vise des objectifs concrets à long terme, avec une discipline patiente qui préfère la construction méthodique à l'impulsivité. Le point sensible se niche dans la légèreté de l'action : cette ambition patiente peut manquer de spontanéité, et le besoin de tout planifier avant d'agir peut retarder une opportunité qui demandait une réaction plus rapide. La leçon à intégrer est d'apprendre qu'une action non planifiée n'est pas forcément une erreur — qu'il y a une force aussi dans l'élan spontané.",
    verseau: "Mars en Verseau combat volontiers pour des causes collectives, avec un côté rebelle assumé face à l'autorité et aux conventions établies. La friction se joue surtout dans l'intérêt personnel : cette énergie mobilisée pour le collectif peut avoir du mal à se déployer aussi facilement pour un objectif purement individuel, comme si l'action avait besoin d'une justification plus large que soi-même pour se sentir légitime. La leçon à intégrer est d'apprendre qu'agir pour son propre bénéfice n'est pas moins noble qu'agir pour une cause — que les deux peuvent coexister sans contradiction.",
    poissons: "Mars en Poissons agit de façon moins frontale, guidé par l'intuition plutôt que par la confrontation directe, avec une énergie qui préfère s'engager pour des causes idéalistes plutôt que pour un bénéfice personnel affiché. L'ombre de ce placement se cache dans l'affirmation de soi : cet évitement du conflit direct peut se transformer en incapacité à défendre clairement ses propres intérêts, laissant l'énergie se diluer dans le compromis ou le renoncement silencieux. Le travail intérieur consiste à apprendre à agir pour soi sans que cela nécessite une cause plus grande pour se justifier — à s'autoriser un désir purement personnel.",
  },
  jupiter: {
    belier: "Jupiter en Bélier construit la confiance par l'audace : on grandit en osant, en se lançant le premier, avec la conviction presque innée que prendre les devants attire la chance. Ce qui coûte le plus se joue dans la persévérance : cet optimisme d'entrée de jeu peut retomber si le résultat n'est pas immédiat, et l'expansion cherchée peut rester à l'état de premier élan jamais consolidé. Le travail intérieur consiste à apprendre que la vraie croissance se mesure aussi à ce qu'on tient dans la durée, pas seulement à ce qu'on ose au départ.",
    taureau: "Jupiter en Taureau construit la confiance par l'accumulation concrète : on grandit en consolidant ce qui existe déjà, avec un sens aigu de l'abondance sensorielle et matérielle plutôt qu'un optimisme abstrait. Le nœud se trouve dans l'excès : cette générosité naturelle peut glisser vers la gourmandise ou l'accumulation pour l'accumulation, une croissance qui se confond avec le \"toujours plus\" plutôt qu'avec un vrai enrichissement intérieur. Ce qu'il y a à travailler ici est d'apprendre que l'abondance ne se mesure pas qu'en quantité — qu'on peut grandir en approfondissant ce qu'on a déjà, sans chercher à en accumuler davantage.",
    gemeaux: "Jupiter en Gémeaux construit la confiance par la curiosité : on grandit en multipliant les échanges, les lectures, les points de vue, avec la conviction que chaque nouvelle information élargit vraiment l'horizon. La difficulté principale se loge dans la cohérence : cette accumulation de savoirs variés peut rester en surface, un éparpillement de connaissances jamais reliées entre elles en une vision d'ensemble. Ce qu'il y a à travailler ici est d'apprendre à relier ce qu'on apprend en un fil cohérent, pour que la curiosité devienne une vraie sagesse plutôt qu'une collection de savoirs isolés.",
    cancer: "Jupiter en Cancer construit la confiance par le lien affectif : on grandit en prenant soin, en se sentant appartenir à un cercle protecteur, en donnant sans compter à ceux qu'on aime. Le revers se joue dans les limites : cette générosité affective peut déborder jusqu'à l'excès de protection ou de sacrifice pour l'autre, une croissance qui s'arrête à la porte de sa propre famille plutôt que de s'ouvrir plus largement. Grandir ici consiste à apprendre que la même générosité peut s'étendre au-delà du cercle familier sans perdre sa chaleur.",
    lion: "Jupiter en Lion construit une confiance généreuse et rayonnante : on grandit en s'exposant, en créant, en misant sur sa propre valeur avec un optimisme qui peut sembler démesuré vu de l'extérieur. La tension se loge dans la mesure : cette confiance en soi peut déraper en surestimation, un optimisme qui ne voit plus les obstacles réels et prend des risques disproportionnés par excès d'assurance. Grandir ici consiste à apprendre à garder ce rayonnement tout en restant capable d'entendre une limite réelle sans la vivre comme une remise en cause de sa valeur.",
    vierge: "Jupiter en Vierge construit la confiance par la compétence : on grandit en perfectionnant un savoir-faire concret, en se rendant utile, avec une exigence de qualité qui peut freiner l'élan naturellement expansif de cette planète. Le point sensible se niche dans le doute : ce souci du détail peut empêcher de reconnaître ses propres progrès, retardant indéfiniment le moment où l'on s'autorise à se sentir compétent·e. Ce placement invite à apprendre à célébrer une réussite avant qu'elle ne soit parfaite — à laisser la confiance grandir au même rythme que la compétence, pas après elle.",
    balance: "Jupiter en Balance construit la confiance à travers la relation : on grandit en s'associant, en recherchant l'équilibre et le consensus, avec la conviction que la croissance passe rarement par la solitude. La friction se joue surtout dans l'autonomie : ce besoin d'association peut freiner une décision qui demanderait d'avancer seul·e, retardant une expansion qui n'attend pas nécessairement l'accord de tous. Ce placement invite à apprendre qu'on peut grandir en dehors d'un consensus — que la confiance en soi n'a pas toujours besoin d'être validée par l'autre.",
    scorpion: "Jupiter en Scorpion construit la confiance dans l'intensité : on grandit en traversant des épreuves profondes plutôt qu'en restant à la surface, avec la conviction que ce qui ne se transforme pas en profondeur ne fait que passer sans vraiment enrichir. L'ombre de ce placement se cache dans le contrôle : cette croissance par la crise peut créer une méfiance envers tout ce qui vient facilement, comme si seule l'épreuve avait de la valeur. Le terrain de maturation consiste à apprendre qu'une opportunité peut être légitime même sans avoir été durement gagnée.",
    sagittaire: "Jupiter est ici dans son élément : la confiance se construit par la foi presque naturelle en l'avenir, une soif de sens et d'horizons larges qui rend l'optimisme presque instinctif. Ce qui coûte le plus se joue dans le réalisme : cette confiance spontanée peut faire sous-estimer les obstacles concrets, promettant plus que ce qui peut réellement être tenu. Le terrain de maturation est d'apprendre à ancrer cette foi en l'avenir dans une vérification réaliste, sans pour autant éteindre l'enthousiasme qui la rend si précieuse.",
    capricorne: "Jupiter en Capricorne construit la confiance dans la durée : on grandit lentement mais solidement, en gagnant une autorité méritée par l'effort plutôt qu'offerte gratuitement. Le nœud se trouve dans la spontanéité de la croissance : cette approche disciplinée peut brider l'expansion naturelle de Jupiter, refusant une opportunité simplement parce qu'elle n'a pas été suffisamment méritée ou planifiée. La vraie maturation consiste à apprendre qu'on a le droit de recevoir une chance sans l'avoir totalement méritée au préalable.",
    verseau: "Jupiter en Verseau construit la confiance dans la différence assumée : on grandit en s'ouvrant à des idées nouvelles et à des causes plus larges que soi, avec un sentiment d'appartenance à quelque chose qui dépasse l'individu. La difficulté principale se loge dans l'ancrage personnel : cette croissance tournée vers le collectif peut négliger un épanouissement plus intime et individuel, comme si la réussite personnelle seule ne suffisait jamais à justifier la confiance en soi. La vraie maturation consiste à apprendre que grandir pour soi-même a autant de valeur que grandir pour une cause collective.",
    poissons: "Jupiter en Poissons construit la confiance dans le lâcher-prise : on grandit en faisant confiance à un mouvement plus grand que soi, une intuition ou une spiritualité qui guide au-delà du contrôle rationnel. Le revers se joue dans le sens du réel : cette foi dans l'invisible peut faire perdre pied avec les contraintes concrètes, menant à des décisions généreuses mais mal ancrées dans la réalité pratique. La leçon à intégrer est d'apprendre à garder un pied dans le concret tout en cultivant cette confiance intuitive — pour que le lâcher-prise reste une force plutôt qu'une fuite.",
  },
  saturn: {
    belier: "Une discipline qui s'apprend par l'action : Saturne freine l'impulsivité naturelle du Bélier, ce qui peut être vécu comme une frustration avant de devenir une force de patience. La tension se loge dans l'attente : ce frein peut donner un sentiment durable de retard sur les autres, comme si l'élan devait toujours être justifié ou mérité avant de pouvoir se déployer. La vraie maturation consiste à apprendre que l'action retenue n'est pas une action manquée — que la patience acquise devient, avec le temps, un véritable atout stratégique.",
    taureau: "Saturne est particulièrement à l'aise ici : sens naturel de la construction lente, de la solidité, de la valeur qui se mérite plutôt qu'elle ne se donne. Le point sensible se niche dans la peur de la perte : cette solidité si durement acquise peut faire craindre tout changement, même positif, comme une menace pour ce qui a mis tant de temps à se construire. Le travail intérieur consiste à apprendre qu'une base solide peut aussi évoluer sans s'effondrer.",
    gemeaux: "Une discipline qui s'apprend par la rigueur intellectuelle : Saturne canalise la dispersion naturelle des Gémeaux vers un savoir plus structuré, parfois au prix de la spontanéité. La friction se joue surtout dans l'auto-censure : la peur de dire une bêtise ou de paraître superficiel peut brider une pensée qui a pourtant besoin de circuler librement pour rester vivante. La leçon à intégrer est d'apprendre que la rigueur et la légèreté d'esprit peuvent coexister — qu'on peut structurer sa pensée sans en éteindre le mouvement.",
    cancer: "Un contrôle qui se muscle dans le rapport à la famille et à la sécurité affective : souvent un sentiment de responsabilité précoce, ou une pudeur émotionnelle à dépasser. L'ombre de ce placement se cache dans la demande d'aide : avoir dû se montrer fiable très tôt rend souvent difficile de redevenir, à l'âge adulte, quelqu'un qu'on prend soin de plutôt que quelqu'un qui prend soin des autres. Ce qu'il y a à travailler ici est d'apprendre qu'on a le droit d'être soutenu·e sans que cela remette en cause la responsabilité qu'on a su assumer.",
    lion: "Une maturité qui se développe dans le rapport à la reconnaissance : la confiance en soi doit ici se construire pas à pas, souvent après avoir douté de sa propre valeur plus profondément que ce qui se voit de l'extérieur. Ce qui coûte le plus se joue dans la comparaison : ce doute initial peut pousser à mesurer sa valeur à celle des autres plutôt qu'à une conviction intérieure stable. Le travail intérieur consiste à apprendre que la reconnaissance méritée avec tant d'efforts finit par devenir une confiance qui ne dépend plus du regard extérieur.",
    vierge: "Un apprentissage qui se fait dans le rapport au détail et à l'exigence : le perfectionnisme naturel de la Vierge peut ici devenir sévérité envers soi-même, à assouplir avec le temps. Le nœud se trouve dans le sentiment de jamais assez : cette exigence redoublée peut transformer chaque tâche accomplie en occasion de repérer ce qui manque encore, plutôt que ce qui a été réussi. Grandir ici consiste à apprendre à reconnaître un travail \"suffisamment bon\" sans attendre la perfection pour s'en satisfaire.",
    balance: "Une leçon qui s'installe dans la relation : engagement mesuré, sens aigu de la justice, mais aussi une peur initiale de l'engagement à dépasser pour construire du solide à deux. La difficulté principale se loge dans la solitude redoutée : cette prudence relationnelle peut retarder longtemps un engagement pourtant désiré, par peur de faire le mauvais choix ou de s'y perdre. Ce qu'il y a à travailler ici est d'apprendre qu'un engagement pris avec sérieux, même tardivement, a toute sa valeur — que la prudence n'empêche pas la solidité.",
    scorpion: "Une discipline qui s'apprend dans le rapport au contrôle et à la transformation : besoin de maîtriser l'intensité intérieure plutôt que de la fuir ou de la subir. Le revers se joue dans le lâcher-prise : cette discipline du contrôle peut devenir une façon d'éviter toute vulnérabilité, comme si perdre la maîtrise équivalait à perdre toute sécurité. Ce placement invite à apprendre qu'une intensité canalisée avec discipline peut aussi, par moments, être relâchée sans danger.",
    sagittaire: "Une rigueur qui se construit dans le rapport aux croyances : Saturne structure l'enthousiasme du Sagittaire, l'obligeant à vérifier concrètement ce en quoi il croit. La tension se loge dans le doute existentiel : cette vérification permanente peut ébranler une foi qui avait justement besoin d'un peu de naïveté pour rester vivante et motivante. Grandir ici consiste à apprendre qu'une croyance peut être à la fois vérifiée sérieusement et vécue avec enthousiasme, sans que l'une n'annule l'autre.",
    capricorne: "Saturne est ici dans son élément : sens inné de la responsabilité, de la structure et de l'ambition patiente — souvent une maturité précoce, qui se bonifie avec l'âge. Le point sensible se niche dans la légèreté : cette maturité assumée tôt peut avoir privé d'une part d'insouciance qui, ailleurs, se vit sans arrière-pensée. Le terrain de maturation consiste à apprendre, souvent tardivement, à se détendre et à jouer sans avoir le sentiment de perdre du temps utile.",
    verseau: "Un contrôle qui se muscle dans le rapport au groupe et à la différence : structurer sa singularité pour qu'elle serve un projet collectif plutôt que de rester marginale. La friction se joue surtout dans l'appartenance : cette structuration peut être vécue comme un renoncement à une part de sa différence, comme s'il fallait choisir entre être soi-même et être utile au groupe. Ce placement invite à apprendre qu'on peut structurer sa singularité sans la dissoudre — qu'elle devient souvent plus utile encore une fois canalisée.",
    poissons: "Une maturité qui se développe dans le rapport au flou et au lâcher-prise : donner une forme concrète à l'intuition et à la sensibilité, sans les étouffer. L'ombre de ce placement se cache dans la rigidité : cette recherche de structure peut, si elle va trop loin, assécher justement ce qui faisait la richesse de cette sensibilité intuitive. La leçon à intégrer est d'apprendre qu'une structure légère peut accueillir le flou plutôt que de chercher à l'éliminer entièrement.",
  },
  asc: {
    belier: "L'Ascendant en Bélier fonctionne comme une armure d'énergie : la première image donnée est celle de quelqu'un prêt à foncer, à trancher, à aller droit au but sans détour ni hésitation apparente. Ce qui coûte le plus se joue dans ce que cette vivacité masque : cet abord frontal peut être une façon de prendre les devants avant que le monde n'ait le temps de le faire, une stratégie de protection déguisée en assurance. La vraie maturation consiste à apprendre que cette énergie n'a pas besoin d'être en permanence sur la défensive pour rester authentique.",
    taureau: "L'Ascendant en Taureau fonctionne comme un ancrage : la présence posée, le rythme lent, la solidité de l'allure inspirent confiance et donnent l'image de quelqu'un difficile à déstabiliser. Le nœud se trouve dans le changement : cette image de stabilité peut devenir un rôle à tenir même quand, à l'intérieur, quelque chose bouge et demanderait à être exprimé. La leçon à intégrer est d'apprendre que montrer une hésitation ou un changement ne fissure pas l'image rassurante — elle l'humanise.",
    gemeaux: "L'Ascendant en Gémeaux fonctionne comme un aimant social : l'abord vif, curieux, bavard capte vite l'attention, et l'allure souvent jeune ou mobile donne une image d'accessibilité immédiate. La difficulté principale se loge dans la profondeur perçue : cette aisance de façade peut donner l'impression de quelqu'un de léger ou de superficiel, alors qu'elle sert surtout à tester le terrain avant de se livrer davantage. Le travail intérieur consiste à apprendre à laisser transparaître, quand la confiance est là, ce qui se cache derrière la conversation facile.",
    cancer: "L'Ascendant en Cancer fonctionne comme un sas protecteur : la présence douce et sensible reste réservée au premier abord, le temps d'évaluer si l'environnement est vraiment sûr avant de se livrer davantage. Le revers se joue dans le rythme de la confiance : cette prudence initiale peut être mal interprétée comme du désintérêt ou de la froideur, alors qu'elle protège une sensibilité bien réelle. Le travail intérieur consiste à apprendre à signaler, même discrètement, que la réserve initiale n'est pas un rejet mais une précaution.",
    lion: "L'Ascendant en Lion fonctionne comme une scène : l'allure ne passe pas inaperçue, portée par la prestance, la chaleur et un sens naturel de la mise en scène de soi qui capte le regard sans effort apparent. La tension se loge dans la dépendance à ce regard : cette image rayonnante peut devenir un rôle épuisant à tenir en continu, comme si la moindre baisse d'énergie risquait de ternir l'image donnée. La vraie maturation consiste à apprendre qu'on peut se montrer fatigué·e ou incertain·e sans perdre l'éclat qu'on projette naturellement.",
    vierge: "L'Ascendant en Vierge fonctionne comme une carte de visite de compétence : la présence discrète et soignée est souvent perçue comme sérieuse et fiable dès le premier contact, presque avant d'avoir prouvé quoi que ce soit. Le point sensible se niche dans la pression de l'image : cette réputation de compétence installée si vite peut rendre difficile de montrer une hésitation ou une erreur sans craindre de décevoir l'image donnée. Ce qu'il y a à travailler ici est d'apprendre que l'imperfection visible ne détruit pas la confiance qu'on inspire — elle la rend souvent plus proche.",
    balance: "L'Ascendant en Balance fonctionne comme un art du contact : l'abord charmant, courtois, esthétiquement soigné donne d'emblée l'image de quelqu'un qui veut créer une relation agréable plutôt qu'un rapport de force. La friction se joue surtout dans l'authenticité : ce souci de faire bonne impression peut se transformer en une façade qui dit ce qu'on pense que l'autre veut entendre, plutôt que ce qu'on pense vraiment. La leçon à intégrer est d'apprendre qu'un désaccord exprimé avec la même grâce ne casse pas le charme — il l'approfondit.",
    scorpion: "L'Ascendant en Scorpion fonctionne comme un rideau à demi tiré : la présence magnétique et intense intrigue d'emblée, laissant deviner une profondeur qui ne se dévoile jamais complètement au premier regard. L'ombre de ce placement se cache dans l'accessibilité : cette intensité peut intimider ou tenir les autres à distance avant même qu'un vrai contact n'ait eu lieu, renforçant malgré soi une image de mystère qu'on ne cherchait pas forcément à cultiver. Grandir ici consiste à apprendre qu'on peut se montrer accessible sans perdre cette profondeur qui fait le charme du personnage.",
    sagittaire: "L'Ascendant en Sagittaire fonctionne comme une invitation au voyage : l'allure enjouée, franche, souvent débordante d'enthousiasme donne d'emblée une carte de visite faite d'humour et d'optimisme contagieux. Ce qui coûte le plus se joue dans la profondeur perçue : cette légèreté apparente peut faire sous-estimer, par les autres comme par soi-même, la vraie substance ou la vraie douleur qui se cache parfois derrière le sourire facile. Le travail intérieur consiste à apprendre à laisser transparaître un vrai sérieux sans craindre de perdre cette légèreté qui reste une vraie force.",
    capricorne: "L'Ascendant en Capricorne fonctionne comme une façade de solidité : la présence sobre et réservée inspire d'emblée le sérieux et la fiabilité, parfois perçue comme distante avant d'être mieux connue. Le nœud se trouve dans la chaleur cachée : cette réserve initiale peut faire manquer, aux yeux des autres, une sensibilité et une chaleur bien réelles mais rarement montrées d'emblée. Ce placement invite à apprendre que se montrer chaleureux plus tôt ne fragilise pas l'image de sérieux — elle la complète.",
    verseau: "L'Ascendant en Verseau fonctionne comme une déclaration d'indépendance : l'abord original, un brin décalé, affiche sa différence sans complexe dès la première rencontre, presque comme une carte de visite assumée. La difficulté principale se loge dans l'appartenance : cette différence revendiquée d'emblée peut, sans le vouloir, tenir les autres à distance avant même qu'un vrai lien n'ait eu le temps de se former. Ce qu'il y a à travailler ici est d'apprendre que se montrer proche des autres, même brièvement, n'efface pas la singularité qu'on tient tant à afficher.",
    poissons: "L'Ascendant en Poissons fonctionne comme un voile discret : la présence douce et rêveuse semble souvent portée ailleurs, insaisissable, comme si une partie de la personne restait toujours un peu hors du présent immédiat. Le revers se joue dans la lisibilité : cette allure poreuse peut donner une image floue, difficile à cerner, que les autres interprètent parfois à leur propre façon plutôt que telle qu'elle est réellement. Le terrain de maturation consiste à apprendre à donner, de temps en temps, un contour plus net à cette présence, sans pour autant sacrifier la douceur qui la caractérise.",
  },
};
